using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class InstallYoungStreetWalkers {public static object Main(string fromText,string countText){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Idle required");EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");var d=Object.FindFirstObjectByType<Chapter45Director>();int from=int.Parse(fromText),count=int.Parse(countText);string marker="Preserved_YoungWalkerBatch_"+from;if(d.transform.Find(marker)!=null)throw new Exception("Already installed");var backup="outputs/chapter45-detailed-design-2026-10-03/scene-recovery/Jamsil-before-young-walkers-"+from+".unity";File.Copy(d.gameObject.scene.path,backup,false);var archive=new GameObject(marker);archive.transform.SetParent(d.transform,false);archive.SetActive(false);var rows=new List<object>();var lives=d.GetComponentsInChildren<Chapter4StreetLife>(true).OrderBy(l=>l.station).ToArray();int total=0;for(int block=from;block<Mathf.Min(from+count,lives.Length);block++){var life=lives[block];int changed=0;for(int i=0;i<life.walkers.Length;i++){if(i%4==3)continue;var walker=life.walkers[i];var old=walker.body;var parent=old.parent;var id=new[]{"CH07","CH08","CH09"}[(i+block)%3];var body=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/"+id+"/"+id+".prefab"),parent);body.name="Young pedestrian "+block+" "+i+" "+id;body.transform.localPosition=walker.origin;body.transform.localRotation=old.localRotation;body.SetActive(old.gameObject.activeSelf);if(body.GetComponentsInChildren<Collider>(true).Length!=0)throw new Exception("Decorative collider added");old.SetParent(archive.transform,true);old.gameObject.SetActive(false);walker.body=body.transform;walker.animator=body.GetComponentInChildren<Animator>(true);changed++;total++;}EditorUtility.SetDirty(life);rows.Add(new{block,life.station,changed,preserved=life.walkers.Length-changed});}EditorSceneManager.MarkSceneDirty(d.gameObject.scene);EditorSceneManager.SaveScene(d.gameObject.scene);return new{from,count,blocks=lives.Length,total,items=rows,collidersAdded=0,motionDriver="Existing nearby-window, path, origin, phase and travel preserved"};}}
